import{_ as e,o,c as i,a1 as s}from"./chunks/framework.DdbKPUhY.js";const u=JSON.parse('{"title":"TLS API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/tls-api.md","filePath":"spec/tls-api.md"}'),r={name:"spec/tls-api.md"};function n(l,t,a,c,d,_){return o(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="tls-api-spec" tabindex="-1">TLS API Spec <a class="header-anchor" href="#tls-api-spec" aria-label="Permalink to &quot;TLS API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The TLS module provides Transport Layer Security (TLS) for HTTP connections, implemented on top of mbedTLS 3.x. It manages TLS context creation, certificate/key loading, cipher suite configuration, TLS 1.3 support, mutual TLS (mTLS), session caching, and TLS handshake lifecycle. The module is guarded by the <code>UVHTTP_FEATURE_TLS</code> compile-time feature gate.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-tls-context-new" tabindex="-1">uvhttp_tls_context_new <a class="header-anchor" href="#uvhttp-tls-context-new" aria-label="Permalink to &quot;uvhttp_tls_context_new&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_new(uvhttp_tls_context_t** ctx)</code></li><li><strong>Purpose</strong>: Create a new TLS context with default mbedTLS server configuration</li><li><strong>Preconditions</strong>: <code>ctx</code> must be a non-NULL pointer to <code>uvhttp_tls_context_t*</code>.</li><li><strong>Postconditions</strong>: On success, <code>*ctx</code> points to a valid TLS context with initialized mbedTLS config, entropy, DRBG, certificate store, and SSL cache. Defaults to server mode with stream transport and preset defaults. On failure, <code>*ctx</code> is set to NULL.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>ctx</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li><li><code>UVHTTP_ERROR_TLS_INIT</code>: DRBG seeding failed</li><li><code>UVHTTP_ERROR_TLS_CONTEXT</code>: mbedtls_ssl_config_defaults failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-free" tabindex="-1">uvhttp_tls_context_free <a class="header-anchor" href="#uvhttp-tls-context-free" aria-label="Permalink to &quot;uvhttp_tls_context_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_tls_context_free(uvhttp_tls_context_t* ctx)</code></li><li><strong>Purpose</strong>: Free a TLS context and all associated mbedTLS resources</li><li><strong>Preconditions</strong>: <code>ctx</code> can be NULL (no-op). Must have been created by <code>uvhttp_tls_context_new</code>.</li><li><strong>Postconditions</strong>: All mbedTLS contexts (SSL config, certificates, private key, CA cert, CRL, entropy, DRBG, cache) are freed. The context memory is released. The pointer is invalid after return.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-load-cert" tabindex="-1">uvhttp_tls_context_load_cert <a class="header-anchor" href="#uvhttp-tls-context-load-cert" aria-label="Permalink to &quot;uvhttp_tls_context_load_cert&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_load_cert_chain(uvhttp_tls_context_t* ctx, const char* cert_file)</code></li><li><strong>Purpose</strong>: Load a certificate (chain) from a PEM file</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. <code>cert_file</code> must be non-NULL and point to a readable PEM file.</li><li><strong>Postconditions</strong>: The certificate is parsed and configured as the server&#39;s own certificate.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> or <code>cert_file</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_CERT</code>: mbedTLS cert parse or config failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-load-key" tabindex="-1">uvhttp_tls_context_load_key <a class="header-anchor" href="#uvhttp-tls-context-load-key" aria-label="Permalink to &quot;uvhttp_tls_context_load_key&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_load_private_key(uvhttp_tls_context_t* ctx, const char* key_file)</code></li><li><strong>Purpose</strong>: Load a private key from a PEM file</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. <code>key_file</code> must be non-NULL and point to a readable PEM key file. The certificate should have been loaded first (<code>uvhttp_tls_context_load_cert_chain</code>).</li><li><strong>Postconditions</strong>: The private key is parsed and associated with the context.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> or <code>key_file</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_KEY</code>: mbedTLS key parse failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-load-ca-file" tabindex="-1">uvhttp_tls_context_load_ca_file <a class="header-anchor" href="#uvhttp-tls-context-load-ca-file" aria-label="Permalink to &quot;uvhttp_tls_context_load_ca_file&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_load_ca_file(uvhttp_tls_context_t* ctx, const char* ca_file)</code></li><li><strong>Purpose</strong>: Load a CA certificate file for client certificate verification</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. <code>ca_file</code> must be non-NULL.</li><li><strong>Postconditions</strong>: The CA certificate is parsed and is set as the trusted CA chain for verification.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> or <code>ca_file</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_CA</code>: mbedTLS CA cert parse failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-enable-tls13" tabindex="-1">uvhttp_tls_context_enable_tls13 <a class="header-anchor" href="#uvhttp-tls-context-enable-tls13" aria-label="Permalink to &quot;uvhttp_tls_context_enable_tls13&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_enable_tls13(uvhttp_tls_context_t* ctx, int enable)</code></li><li><strong>Purpose</strong>: Enable or disable TLS 1.3 (minimum version)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: When enabled, the minimum TLS version is set to TLS 1.3 (MBEDTLS_SSL_MINOR_VERSION_4). When disabled, the minimum is set to TLS 1.2 (MBEDTLS_SSL_MINOR_VERSION_3).</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-set-cipher-suites" tabindex="-1">uvhttp_tls_context_set_cipher_suites <a class="header-anchor" href="#uvhttp-tls-context-set-cipher-suites" aria-label="Permalink to &quot;uvhttp_tls_context_set_cipher_suites&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_set_cipher_suites(uvhttp_tls_context_t* ctx, const int* cipher_suites)</code></li><li><strong>Purpose</strong>: Set the preferred cipher suites for the TLS context</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. <code>cipher_suites</code> must be non-NULL and point to a zero-terminated array of mbedTLS cipher suite identifiers.</li><li><strong>Postconditions</strong>: The TLS configuration uses the specified cipher suites in preference order.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> or <code>cipher_suites</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-enable-client-auth" tabindex="-1">uvhttp_tls_context_enable_client_auth <a class="header-anchor" href="#uvhttp-tls-context-enable-client-auth" aria-label="Permalink to &quot;uvhttp_tls_context_enable_client_auth&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_enable_client_auth(uvhttp_tls_context_t* ctx, int require_cert)</code></li><li><strong>Purpose</strong>: Enable or disable client certificate authentication (mTLS)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: When <code>require_cert</code> is non-zero, auth mode is set to <code>MBEDTLS_SSL_VERIFY_REQUIRED</code> (client must present a valid certificate). When zero, auth mode is <code>MBEDTLS_SSL_VERIFY_NONE</code>.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-set-verify-depth" tabindex="-1">uvhttp_tls_context_set_verify_depth <a class="header-anchor" href="#uvhttp-tls-context-set-verify-depth" aria-label="Permalink to &quot;uvhttp_tls_context_set_verify_depth&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_set_verify_depth(uvhttp_tls_context_t* ctx, int depth)</code></li><li><strong>Purpose</strong>: Set the certificate chain verification depth (currently a no-op placeholder)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Currently returns UVHTTP_OK without modification (reserved for future use).</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-enable-session-tickets" tabindex="-1">uvhttp_tls_context_enable_session_tickets <a class="header-anchor" href="#uvhttp-tls-context-enable-session-tickets" aria-label="Permalink to &quot;uvhttp_tls_context_enable_session_tickets&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_enable_session_tickets(uvhttp_tls_context_t* ctx, int enable)</code></li><li><strong>Purpose</strong>: Enable or disable TLS session tickets (currently a no-op placeholder)</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Returns UVHTTP_OK. Session ticket support is temporarily disabled in the mbedTLS configuration.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-context-set-session-cache" tabindex="-1">uvhttp_tls_context_set_session_cache <a class="header-anchor" href="#uvhttp-tls-context-set-session-cache" aria-label="Permalink to &quot;uvhttp_tls_context_set_session_cache&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_context_set_session_cache(uvhttp_tls_context_t* ctx, int max_sessions)</code></li><li><strong>Purpose</strong>: Set the maximum number of entries in the TLS session cache</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. <code>max_sessions</code> must be &gt;= 0.</li><li><strong>Postconditions</strong>: The session cache entry limit is updated.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-create-ssl" tabindex="-1">uvhttp_tls_create_ssl <a class="header-anchor" href="#uvhttp-tls-create-ssl" aria-label="Permalink to &quot;uvhttp_tls_create_ssl&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>mbedtls_ssl_context* uvhttp_tls_create_ssl(uvhttp_tls_context_t* ctx)</code></li><li><strong>Purpose</strong>: Create an SSL session context from a TLS context</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid.</li><li><strong>Postconditions</strong>: Returns a valid mbedTLS SSL context on success, NULL on failure.</li><li><strong>Error conditions</strong>: <ul><li>Returns NULL: <code>ctx</code> is NULL, allocation failure, or mbedtls_ssl_setup failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-setup-ssl" tabindex="-1">uvhttp_tls_setup_ssl <a class="header-anchor" href="#uvhttp-tls-setup-ssl" aria-label="Permalink to &quot;uvhttp_tls_setup_ssl&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_setup_ssl(mbedtls_ssl_context* ssl, int fd)</code></li><li><strong>Purpose</strong>: Attach a socket file descriptor to an SSL context for BIO</li><li><strong>Preconditions</strong>: <code>ssl</code> must be non-NULL. <code>fd</code> must be a valid socket descriptor.</li><li><strong>Postconditions</strong>: Custom BIO callbacks (<code>mbedtls_net_send</code>/<code>mbedtls_net_recv</code>) are set on the SSL context, using the provided file descriptor.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ssl</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-handshake" tabindex="-1">uvhttp_tls_handshake <a class="header-anchor" href="#uvhttp-tls-handshake" aria-label="Permalink to &quot;uvhttp_tls_handshake&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_handshake(mbedtls_ssl_context* ssl)</code></li><li><strong>Purpose</strong>: Perform the TLS handshake (non-blocking)</li><li><strong>Preconditions</strong>: <code>ssl</code> must be non-NULL and must have been set up with a socket via <code>uvhttp_tls_setup_ssl</code>.</li><li><strong>Postconditions</strong>: On success, the TLS handshake is complete. Non-blocking states return specific error codes.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ssl</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_WANT_READ</code>: handshake needs more data from socket (non-blocking)</li><li><code>UVHTTP_ERROR_TLS_WANT_WRITE</code>: handshake needs to write to socket (non-blocking)</li><li><code>UVHTTP_ERROR_TLS_HANDSHAKE</code>: handshake failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-read" tabindex="-1">uvhttp_tls_read <a class="header-anchor" href="#uvhttp-tls-read" aria-label="Permalink to &quot;uvhttp_tls_read&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_read(mbedtls_ssl_context* ssl, void* buf, size_t len)</code></li><li><strong>Purpose</strong>: Read decrypted data from a TLS connection</li><li><strong>Preconditions</strong>: <code>ssl</code> must be non-NULL and handshake must be complete. <code>buf</code> must be non-NULL.</li><li><strong>Postconditions</strong>: On success, returns the number of bytes read (positive value). On non-blocking WANT_READ/WANT_WRITE, returns the corresponding error code.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ssl</code> or <code>buf</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_WANT_READ</code>: non-blocking, need more data</li><li><code>UVHTTP_ERROR_TLS_WANT_WRITE</code>: non-blocking, need to write</li><li><code>UVHTTP_ERROR_TLS_READ</code>: read error</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-write" tabindex="-1">uvhttp_tls_write <a class="header-anchor" href="#uvhttp-tls-write" aria-label="Permalink to &quot;uvhttp_tls_write&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_write(mbedtls_ssl_context* ssl, const void* buf, size_t len)</code></li><li><strong>Purpose</strong>: Write encrypted data to a TLS connection</li><li><strong>Preconditions</strong>: <code>ssl</code> must be non-NULL and handshake must be complete. <code>buf</code> must be non-NULL.</li><li><strong>Postconditions</strong>: On success, returns the number of bytes written (positive value). On non-blocking WANT_READ/WANT_WRITE, returns the corresponding error code.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ssl</code> or <code>buf</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_WANT_READ</code>: non-blocking, need to read</li><li><code>UVHTTP_ERROR_TLS_WANT_WRITE</code>: non-blocking, need to write</li><li><code>UVHTTP_ERROR_TLS_WRITE</code>: write error</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-init-uvhttp-tls-cleanup" tabindex="-1">uvhttp_tls_init / uvhttp_tls_cleanup <a class="header-anchor" href="#uvhttp-tls-init-uvhttp-tls-cleanup" aria-label="Permalink to &quot;uvhttp_tls_init / uvhttp_tls_cleanup&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_init(uvhttp_context_t* context)</code> / <code>void uvhttp_tls_cleanup(uvhttp_context_t* context)</code></li><li><strong>Purpose</strong>: Initialize/cleanup the global TLS subsystem (entropy source, DRBG)</li><li><strong>Preconditions</strong>: <code>context</code> must be non-NULL. For <code>uvhttp_tls_cleanup</code>, the context must have been initialized.</li><li><strong>Postconditions</strong>: <code>context-&gt;tls_initialized</code> is set to 1 on success, 0 after cleanup.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>context</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_INIT</code>: DRBG seeding failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-verify-peer-cert" tabindex="-1">uvhttp_tls_verify_peer_cert <a class="header-anchor" href="#uvhttp-tls-verify-peer-cert" aria-label="Permalink to &quot;uvhttp_tls_verify_peer_cert&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_tls_verify_peer_cert(mbedtls_ssl_context* ssl)</code></li><li><strong>Purpose</strong>: Verify the peer&#39;s certificate chain</li><li><strong>Preconditions</strong>: <code>ssl</code> must be non-NULL and handshake must be complete.</li><li><strong>Postconditions</strong>: Returns 1 if verification succeeded (flags=0), 0 otherwise.</li><li><strong>Thread safety</strong>: Thread-safe for reads after handshake.</li></ul><h3 id="uvhttp-tls-verify-hostname" tabindex="-1">uvhttp_tls_verify_hostname <a class="header-anchor" href="#uvhttp-tls-verify-hostname" aria-label="Permalink to &quot;uvhttp_tls_verify_hostname&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_tls_verify_hostname(mbedtls_x509_crt* cert, const char* hostname)</code></li><li><strong>Purpose</strong>: Verify a hostname against a certificate (CN and SAN)</li><li><strong>Preconditions</strong>: <code>cert</code> and <code>hostname</code> must be non-NULL.</li><li><strong>Postconditions</strong>: Returns 1 if the hostname matches the certificate&#39;s CN or any SAN entry, 0 otherwise.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-tls-check-cert-validity" tabindex="-1">uvhttp_tls_check_cert_validity <a class="header-anchor" href="#uvhttp-tls-check-cert-validity" aria-label="Permalink to &quot;uvhttp_tls_check_cert_validity&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_tls_check_cert_validity(mbedtls_x509_crt* cert)</code></li><li><strong>Purpose</strong>: Check if a certificate is within its validity period</li><li><strong>Preconditions</strong>: <code>cert</code> must be non-NULL.</li><li><strong>Postconditions</strong>: Returns 1 if the certificate is valid (not yet expired and not before its valid_from date), 0 otherwise.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-tls-get-stats-uvhttp-tls-reset-stats" tabindex="-1">uvhttp_tls_get_stats / uvhttp_tls_reset_stats <a class="header-anchor" href="#uvhttp-tls-get-stats-uvhttp-tls-reset-stats" aria-label="Permalink to &quot;uvhttp_tls_get_stats / uvhttp_tls_reset_stats&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_get_stats(uvhttp_tls_context_t* ctx, uvhttp_tls_stats_t* stats)</code> / <code>uvhttp_error_t uvhttp_tls_reset_stats(uvhttp_tls_context_t* ctx)</code></li><li><strong>Purpose</strong>: Get or reset TLS performance statistics</li><li><strong>Preconditions</strong>: <code>ctx</code> must be valid. For <code>uvhttp_tls_get_stats</code>, <code>stats</code> must be non-NULL.</li><li><strong>Postconditions</strong>: Statistics are copied to the output struct or zeroed.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ctx</code> or <code>stats</code> (for get) is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-tls-get-connection-info" tabindex="-1">uvhttp_tls_get_connection_info <a class="header-anchor" href="#uvhttp-tls-get-connection-info" aria-label="Permalink to &quot;uvhttp_tls_get_connection_info&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_tls_get_connection_info(mbedtls_ssl_context* ssl, char* buf, size_t buf_size)</code></li><li><strong>Purpose</strong>: Get a human-readable string with TLS version and cipher suite</li><li><strong>Preconditions</strong>: <code>ssl</code> and <code>buf</code> must be non-NULL.</li><li><strong>Postconditions</strong>: <code>buf</code> is filled with a string like &quot;Version: TLSv1.3, Cipher: TLS-AES-256-GCM-SHA384&quot;.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_TLS_INVALID_PARAM</code>: <code>ssl</code> or <code>buf</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Thread-safe for reads after handshake.</li></ul><h3 id="uvhttp-tls-get-error-string-uvhttp-tls-print-error" tabindex="-1">uvhttp_tls_get_error_string / uvhttp_tls_print_error <a class="header-anchor" href="#uvhttp-tls-get-error-string-uvhttp-tls-print-error" aria-label="Permalink to &quot;uvhttp_tls_get_error_string / uvhttp_tls_print_error&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_tls_get_error_string(int ret, char* buf, size_t buf_size)</code> / <code>void uvhttp_tls_print_error(int ret)</code></li><li><strong>Purpose</strong>: Convert an mbedTLS error code to a human-readable string</li><li><strong>Preconditions</strong>: <code>buf</code> must be non-NULL and <code>buf_size</code> &gt; 0 for <code>uvhttp_tls_get_error_string</code>.</li><li><strong>Postconditions</strong>: The error string is written to the buffer or logged.</li><li><strong>Thread safety</strong>: Thread-safe.</li></ul><h2 id="tls-handshake-lifecycle" tabindex="-1">TLS Handshake Lifecycle <a class="header-anchor" href="#tls-handshake-lifecycle" aria-label="Permalink to &quot;TLS Handshake Lifecycle&quot;">​</a></h2><ol><li><strong>Context creation</strong>: <code>uvhttp_tls_context_new</code> creates a server-side TLS context with default configuration.</li><li><strong>Certificate loading</strong>: <code>uvhttp_tls_context_load_cert_chain</code> loads the server certificate. <code>uvhttp_tls_context_load_private_key</code> loads the corresponding private key.</li><li><strong>Optional CA loading</strong>: <code>uvhttp_tls_context_load_ca_file</code> loads CA certificates for client verification.</li><li><strong>Optional configuration</strong>: Cipher suites, TLS 1.3, mTLS, session cache, and CRL are configured as needed.</li><li><strong>SSL session creation</strong>: <code>uvhttp_tls_create_ssl</code> creates an SSL session from the context.</li><li><strong>BIO setup</strong>: <code>uvhttp_tls_setup_ssl</code> attaches the socket file descriptor to the SSL session.</li><li><strong>Handshake</strong>: <code>uvhttp_tls_handshake</code> performs the TLS handshake. This is non-blocking and may return <code>WANT_READ</code>/<code>WANT_WRITE</code> to be called again after the socket is ready.</li><li><strong>Data transfer</strong>: <code>uvhttp_tls_read</code> and <code>uvhttp_tls_write</code> handle encrypted data transfer.</li><li><strong>Cleanup</strong>: The SSL session is freed by the caller. The TLS context is freed via <code>uvhttp_tls_context_free</code>.</li></ol><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>mbedTLS backend</strong>: All TLS operations are delegated to mbedTLS 3.x. The library provides entropy, DRBG, certificate parsing, SSL handshake, and cipher operations.</p></li><li><p><strong>Non-blocking handshake</strong>: The handshake uses custom BIO callbacks (<code>mbedtls_net_send</code>/<code>mbedtls_net_recv</code>) that translate EAGAIN/EWOULDBLOCK to <code>MBEDTLS_ERR_SSL_WANT_READ</code>/<code>WANT_WRITE</code>. These are propagated to the caller as <code>UVHTTP_ERROR_TLS_WANT_READ</code>/<code>UVHTTP_ERROR_TLS_WANT_WRITE</code> for integration with libuv&#39;s event loop.</p></li><li><p><strong>Session cache</strong>: The session cache is initialized but currently disconnected from the SSL config (pending thread-safety verification). Sessions are not cached in the current version.</p></li><li><p><strong>TLS 1.3 support</strong>: When enabled, the minimum TLS version is set to TLS 1.3 (MBEDTLS_SSL_MINOR_VERSION_4). When disabled, minimum is TLS 1.2.</p></li><li><p><strong>mTLS support</strong>: Client certificate authentication is configurable via <code>uvhttp_tls_context_enable_client_auth</code>. Requires CA certificates to be loaded first.</p></li><li><p><strong>Certificate validation</strong>: The <code>uvhttp_tls_check_cert_validity</code> checks both <code>valid_from</code> and <code>valid_to</code> dates. The <code>uvhttp_tls_verify_peer_cert</code> checks the verification result flags.</p></li><li><p><strong>Hostname verification</strong>: CN (Common Name) and SAN (Subject Alternative Name) are both checked. Uses exact string matching (wildcard support is not yet implemented).</p></li><li><p><strong>CRL checking</strong>: Certificate Revocation List checking can be enabled via <code>uvhttp_tls_context_enable_crl_checking</code>. CRL files are loaded via <code>uvhttp_tls_load_crl_file</code>.</p></li><li><p><strong>Double-free protection</strong>: <code>uvhttp_tls_context_free</code> handles NULL gracefully. All mbedTLS sub-contexts are freed in order.</p></li><li><p><strong>Statistics</strong>: The TLS context tracks handshake count, errors, bytes sent/received, session hits/misses, and average handshake time.</p></li></ol><h2 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h2><ul><li>TLS context creation: O(1) with mbedTLS initialization</li><li>SSL session creation: O(1)</li><li>Handshake: O(n) where n is the certificate chain length; typically 2-3 RTT for TLS 1.2, 1-2 RTT for TLS 1.3</li><li>Data transfer: O(n) where n is the data size; encryption overhead ~5-15% CPU</li><li>Memory: ~1KB per TLS context, ~512 bytes per SSL session</li><li>Cipher suite selection: O(1) via mbedTLS internal lookup</li></ul><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>TLS context creation and destruction</li><li>Certificate and key loading (valid and invalid files)</li><li>TLS 1.3 enable/disable</li><li>Cipher suite configuration</li><li>mTLS client auth enable/disable</li><li>SSL session creation, setup, and handshake</li><li>Non-blocking handshake with WANT_READ/WANT_WRITE handling</li><li>TLS read/write operations</li><li>Peer certificate verification (valid and invalid)</li><li>Hostname verification (CN match, SAN match, no match)</li><li>Certificate validity checking (valid, expired, not-yet-valid)</li><li>Certificate subject/issuer/serial retrieval</li><li>CRL enable and file loading</li><li>Session cache configuration</li><li>TLS statistics get and reset</li><li>Connection info string formatting</li><li>NULL parameter handling for all public functions</li><li>Memory cleanup (no leaks on free)</li><li>Feature gate: builds without UVHTTP_FEATURE_TLS</li></ul>',58)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
